CREATE OR REPLACE FUNCTION platform.protect_succeeded_revision()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP = 'DELETE' OR OLD.success THEN
        RAISE EXCEPTION 'successful schema revision is immutable';
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION platform.reject_reconciliation_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    RAISE EXCEPTION 'reconciliation result is append-only';
    RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.adoc_set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.ki_search_vector_update()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.search_vector :=
        setweight(to_tsvector('english', coalesce(NEW.title, '')), 'A') ||
        setweight(to_tsvector('english', coalesce(NEW.summary, '')), 'B') ||
        setweight(to_tsvector('english', coalesce(NEW.content_text, '')), 'C');
    NEW.updated_at := NOW();
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.ki_set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    -- Don't override if search_vector trigger already set it
    IF NEW.updated_at = OLD.updated_at THEN
        NEW.updated_at := NOW();
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.normalize_team_slug()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.slug := LOWER(TRIM(REGEXP_REPLACE(NEW.slug, '[^a-z0-9-]', '-', 'g')));
    NEW.slug := TRIM(BOTH '-' FROM NEW.slug);
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.normalize_user_email()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.email := LOWER(TRIM(NEW.email));
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.prevent_bootstrap_unlock()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF OLD.is_locked = TRUE AND NEW.is_locked = FALSE THEN
        RAISE EXCEPTION 'Bootstrap lock cannot be reversed';
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.protect_last_team_owner()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    owner_role_id UUID;
    admin_count INT;
BEGIN
    SELECT id INTO owner_role_id FROM roles WHERE name = 'owner';

    -- On role change away from owner
    IF TG_OP = 'UPDATE' AND OLD.role_id = owner_role_id AND NEW.role_id != owner_role_id THEN
        SELECT COUNT(*) INTO admin_count
        FROM team_memberships
        WHERE team_id = NEW.team_id AND role_id = owner_role_id;
        IF admin_count <= 1 THEN
            RAISE EXCEPTION 'Cannot remove the last owner from team';
        END IF;
    END IF;

    -- On deletion of an owner
    IF TG_OP = 'DELETE' AND OLD.role_id = owner_role_id THEN
        SELECT COUNT(*) INTO admin_count
        FROM team_memberships
        WHERE team_id = OLD.team_id AND role_id = owner_role_id;
        IF admin_count <= 1 THEN
            RAISE EXCEPTION 'Cannot remove the last owner from team';
        END IF;
    END IF;

    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.updated_at := NOW();
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.trg_artifacts_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$function$
